// Textos de la ayuda (botón «Ayuda» del menú lateral). Las capturas están en
// assets/ayuda/*.webp (en inglés, assets/ayuda/en/*.webp) y se regeneran con
// `make capturas` y `make capturas-en`.
import type { View } from './state.svelte'
import { t, i18n } from './i18n.svelte'

const shots = import.meta.glob('../assets/ayuda/*.webp', { eager: true, query: '?url', import: 'default' }) as Record<string, string>
const shotsEN = import.meta.glob('../assets/ayuda/en/*.webp', { eager: true, query: '?url', import: 'default' }) as Record<string, string>

/** URL de una captura por su nombre (sin extensión), o undefined si no existe.
 *  En inglés usa la suya; si falta, la de español. */
export function shot(name: string): string | undefined {
  if (i18n.lang === 'en') {
    const en = shotsEN[`../assets/ayuda/en/${name}.webp`]
    if (en) return en
  }
  return shots[`../assets/ayuda/${name}.webp`]
}

export interface HelpStep {
  title: string
  text: string
  img?: string
}

export interface HelpSection {
  id: View | 'general' | 'publicar' | 'probar' | 'fallos'
  title: string
  intro: string
  steps: HelpStep[]
}

